-- ============================================================================
-- Canonical points reference (DEC-035, 2026-09-21). Additive, forward-only,
-- idempotent. Backward-compatible: every new column is nullable or defaulted,
-- no existing column, constraint, policy or row is changed, no data is
-- deleted or rewritten. Rollback plan at the bottom (never needed on prod).
--
-- WHAT
--   1. food_reference_sources  — provenance of an imported sheet (version, sha256).
--   2. food_reference_items    — one row per source row: verbatim source values
--                                (source_*), the cleaned display/category/portion,
--                                base points, status (active / needs_review /
--                                conflict / deprecated), attached rule.
--   3. food_reference_aliases  — verified search aliases → reference item.
--   4. foods                   + portion_amount / portion_unit / points_per_portion /
--                                points_status / created_by_profile_id /
--                                points_confirmed_at (custom foods: confirmed
--                                portion value + owner scope).
--   5. food_entries            + points_basis / reference_item_id / base_points /
--                                benefit_rule (snapshot provenance; the snapshot
--                                itself is the existing food_name/amount/unit/
--                                points_value — historical rows are untouched).
--
-- ACCESS MODEL
--   The reference tables are SHARED and READ-ONLY for the app: SELECT for
--   authenticated household members (every anonymous device session), nothing
--   for anon, writes only by service_role / migrations. Household data keeps
--   its existing RLS (is_household_member). Personal custom foods record their
--   creator in created_by_profile_id.
--
-- SEED
--   The block between the GENERATED markers is produced by
--   `npm run points:seed` from src/data/points-reference/reference.v1.json and
--   upserts on (source_id, source_row) — re-running never duplicates.
-- ============================================================================

-- 1. sources -----------------------------------------------------------------
create table if not exists public.food_reference_sources (
  id text primary key,
  version text not null,
  file_name text not null,
  sha256 text not null,
  sheet text,
  imported_at timestamptz not null default now(),
  unique (id, version)
);

-- 2. items -------------------------------------------------------------------
create table if not exists public.food_reference_items (
  id uuid primary key,
  source_id text not null references public.food_reference_sources (id) on delete restrict,
  source_version text not null,
  source_row integer not null,
  source_name text not null,
  source_quantity_text text,
  source_points numeric not null,
  source_category text,
  display_name text not null,
  normalized_name text not null,
  base_name text,
  category text,
  portion jsonb,
  points numeric not null check (points >= 0),
  status text not null check (status in ('active', 'needs_review', 'conflict', 'deprecated')),
  rule text check (rule is null or rule in ('zero_any_quantity', 'fruit_daily_allowance', 'protein_zero_allowance')),
  benefit_of uuid references public.food_reference_items (id) on delete set null,
  review_reasons text[] not null default '{}',
  cleaning_rules text[] not null default '{}',
  conflict_group text,
  duplicate_of uuid references public.food_reference_items (id) on delete set null,
  notes text[] not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (source_id, source_version, source_row)
);
create index if not exists food_reference_items_normalized_idx
  on public.food_reference_items (normalized_name);
create index if not exists food_reference_items_status_idx
  on public.food_reference_items (status);

-- 3. aliases -----------------------------------------------------------------
create table if not exists public.food_reference_aliases (
  id uuid primary key default gen_random_uuid(),
  item_id uuid not null references public.food_reference_items (id) on delete cascade,
  alias text not null,
  normalized_alias text not null,
  verified boolean not null default false,
  origin text not null default 'manual',
  created_at timestamptz not null default now(),
  unique (normalized_alias, item_id)
);

-- 4. custom foods: confirmed portion value + owner ----------------------------
alter table public.foods add column if not exists portion_amount numeric
  check (portion_amount is null or portion_amount > 0);
alter table public.foods add column if not exists portion_unit text;
alter table public.foods add column if not exists points_per_portion numeric
  check (points_per_portion is null or points_per_portion >= 0);
alter table public.foods add column if not exists points_status text not null default 'unscored'
  check (points_status in ('unscored', 'confirmed'));
alter table public.foods add column if not exists created_by_profile_id uuid
  references public.profiles (id) on delete set null;
alter table public.foods add column if not exists points_confirmed_at timestamptz;

-- 5. entry snapshot provenance -------------------------------------------------
alter table public.food_entries add column if not exists points_basis text;
alter table public.food_entries add column if not exists reference_item_id uuid
  references public.food_reference_items (id) on delete set null;
alter table public.food_entries add column if not exists base_points numeric
  check (base_points is null or base_points >= 0);
alter table public.food_entries add column if not exists benefit_rule text
  check (benefit_rule is null or benefit_rule in ('zero_any_quantity', 'fruit_daily_allowance', 'protein_zero_allowance'));

-- updated_at trigger on the items table ----------------------------------------
drop trigger if exists set_updated_at on public.food_reference_items;
create trigger set_updated_at
  before update on public.food_reference_items
  for each row execute function public.set_updated_at();

-- privileges + RLS: shared read-only reference ----------------------------------
revoke all on table public.food_reference_sources, public.food_reference_items, public.food_reference_aliases
  from anon, authenticated;
grant select on table public.food_reference_sources, public.food_reference_items, public.food_reference_aliases
  to authenticated;
grant select, insert, update, delete
  on table public.food_reference_sources, public.food_reference_items, public.food_reference_aliases
  to service_role;

alter table public.food_reference_sources enable row level security;
alter table public.food_reference_items enable row level security;
alter table public.food_reference_aliases enable row level security;

drop policy if exists food_reference_sources_select on public.food_reference_sources;
create policy food_reference_sources_select on public.food_reference_sources
  for select to authenticated using (auth.uid() is not null);

drop policy if exists food_reference_items_select on public.food_reference_items;
create policy food_reference_items_select on public.food_reference_items
  for select to authenticated using (auth.uid() is not null);

drop policy if exists food_reference_aliases_select on public.food_reference_aliases;
create policy food_reference_aliases_select on public.food_reference_aliases
  for select to authenticated using (auth.uid() is not null);
-- No insert / update / delete policy: with RLS enabled, authenticated cannot write.

